// cc host.c -llua5.4 -I/usr/include/lua5.4 && ./a.out
#include <lua.h>
#include <lauxlib.h>
#include <lualib.h>
#include <stdio.h>
static int c_add(lua_State *L) {
  lua_Integer a = luaL_checkinteger(L, 1);
  lua_Integer b = luaL_checkinteger(L, 2);
  lua_pushinteger(L, a + b);
  return 1;                               /* one result */
}
int main(void) {
  lua_State *L = luaL_newstate();
  luaL_openlibs(L);
  lua_register(L, "add", c_add);
  if (luaL_dostring(L, "return add(2, 40) * 2") != LUA_OK)
    fprintf(stderr, "%s\n", lua_tostring(L, -1));
  else
    printf("%lld\n", (long long)lua_tointeger(L, -1));  /* 84 */
  luaL_dostring(L, "add('x', 1)");
  printf("%s\n", lua_tostring(L, -1));   /* ...bad argument #1 to 'add'... */
  lua_close(L);
  return 0;
}
